// Local Zogg catalogue browser. Original media never enters the public deployment.
export function trimSelection(length,start,duration,kind){start=Number(start);duration=Number(duration);if(!Number.isFinite(start)||!Number.isFinite(duration)||start<0||start>=length||duration<.01)throw Error('Choose a start inside the sound and a positive length');return{start,duration:Math.min(duration,length-start,kind==='sample'?30:300)};}
export class ZoggClient{
 constructor(token,fetcher=globalThis.fetch){this.token=token;this.fetcher=fetcher.bind(globalThis);}
 async api(action,data={}){const r=await this.fetcher('/api/'+action,{method:'POST',headers:{...(this.token?{Authorization:'Bearer '+this.token}:{}),'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(70000)});const result=await r.json();if(!r.ok)throw Error(result.error||'Zogg is unavailable');return result;}
 async audio(path){if(!/^\/audio\/[a-f0-9]{32}$/.test(path))throw Error('Invalid Zogg audio handle');const r=await this.fetcher(path,{headers:this.token?{Authorization:'Bearer '+this.token}:{},signal:AbortSignal.timeout(70000)});if(!r.ok)throw Error('Preview expired. Try Preview again.');return r.arrayBuffer();}
}
export function mountSampleBrowser({root,load,decode,notice}){
 const $=id=>root.querySelector('#'+id);let token='',client=null,offset=0,total=0,selected=null,revision=0,searchVersion=0,busy=false,objectURL=null,requestId=0;
 if(location.hostname==='127.0.0.1')try{const fragment=new URLSearchParams(location.hash.slice(1));token=fragment.get('zogg')||'';sessionStorage.removeItem('pxl-zogg');if(fragment.has('zogg'))history.replaceState(null,'',location.pathname+location.search);}catch{}
 const local=!!token||document.documentElement.dataset.zoggLocal==='true';client=local?new ZoggClient(''):null;const paired=token?new ZoggClient(token).api('pair'):Promise.resolve();$('zogg-connect').hidden=local;$('zogg-browser').hidden=!local;
 function message(s){$('zogg-status').textContent=s;}
 function controls(){for(const id of ['zogg-preview','zogg-sampler','zogg-tape'])$(id).disabled=busy||!selected;$('zogg-prev').disabled=busy||offset===0;$('zogg-next').disabled=busy||offset+25>=total;for(const id of ['zogg-search','zogg-library','zogg-max','zogg-sort','zogg-query','zogg-start','zogg-duration','zogg-track'])$(id).disabled=busy;}
 function stop(){requestId++;$('zogg-audio').hidden=true;$('zogg-audio').pause();$('zogg-audio').removeAttribute('src');$('zogg-audio').load();if(objectURL){URL.revokeObjectURL(objectURL);objectURL=null;}}
 function clear(){stop();selected=null;revision++;$('zogg-name').textContent='SELECT A SOUND';$('zogg-info').textContent='Search your mounted Zogg libraries. Preview to inspect its waveform.';const c=$('zogg-wave').getContext('2d');c.clearRect(0,0,1000,120);controls();}
 async function select(item,row){if(busy)return;clear();const version=revision;selected={...item};root.querySelectorAll('[data-asset]').forEach(b=>b.ariaPressed=String(b===row));$('zogg-name').textContent=item.filename;$('zogg-info').textContent=`${item.duration_seconds.toFixed(2)}s / ${item.match_type==='fuzzy_text'?'FUZZY TEXT':'FILENAME / METADATA'}`;$('zogg-start').value=0;$('zogg-duration').value=Math.min(30,item.duration_seconds).toFixed(2);controls();try{const result=await client.api('inspect',{asset_id:item.asset_id});if(version!==revision)return;selected={...item,...result.asset,asset_id:item.asset_id};$('zogg-info').textContent=`${result.asset.duration_seconds.toFixed(2)}s / ${result.asset.channels}CH / ${result.asset.sample_rate}Hz / ${result.asset.relative_path}`;}catch(e){if(version===revision){selected=null;message(e.message);controls();}}}
 async function search(reset=true){if(!client||busy)return;if(reset)offset=0;const version=++searchVersion;clear();$('zogg-results').replaceChildren();message('Searching Zogg…');try{const max=$('zogg-max').value,library=$('zogg-library').value,r=await client.api('search',{query:$('zogg-query').value,offset,limit:25,sort:$('zogg-sort').value,...(max?{maximum_duration_seconds:+max}:{}),...(library?{library_id:+library}:{})});if(version!==searchVersion)return;clear();total=r.total;$('zogg-results').replaceChildren();for(const item of r.results){const b=document.createElement('button');b.dataset.asset=item.asset_id;b.className='sample-row';b.ariaPressed='false';const name=document.createElement('strong'),detail=document.createElement('small');name.textContent=item.filename;detail.textContent=`${item.duration_seconds.toFixed(2)}s / #${item.asset_id}`;b.append(name,detail);b.onclick=()=>select(item,b);$('zogg-results').append(b);}message(total?`${offset+1}–${Math.min(offset+25,total)} OF ${total.toLocaleString()} / FILENAME + METADATA SEARCH`:'No sounds match. Try a shorter filename or another library.');controls();}catch(e){if(version===searchVersion)message(e.message);}}
 $('zogg-form').onsubmit=e=>{e.preventDefault();search();};for(const id of ['zogg-library','zogg-max','zogg-sort'])$(id).onchange=()=>search();$('zogg-prev').onclick=()=>{offset=Math.max(0,offset-25);search(false);};$('zogg-next').onclick=()=>{offset+=25;search(false);};$('zogg-preview-stop').onclick=stop;
 for(const id of ['zogg-start','zogg-duration'])$(id).onchange=()=>{revision++;stop();};
 $('zogg-preview').onclick=async()=>{if(!selected||busy)return;stop();const id=requestId,version=revision,item=selected;try{const trim=trimSelection(item.duration_seconds,$('zogg-start').value,$('zogg-duration').value,'tape');message('Preparing preview…');const r=await client.api('preview',{asset_id:item.asset_id,start:trim.start,duration:Math.min(15,trim.duration)}),bytes=await client.audio(r.audio);if(version!==revision||id!==requestId)return;const audio=await decode(bytes.slice(0));if(version!==revision||id!==requestId)return;objectURL=URL.createObjectURL(new Blob([bytes],{type:'audio/wav'}));$('zogg-audio').src=objectURL;$('zogg-audio').hidden=false;const canvas=$('zogg-wave'),ctx=canvas.getContext('2d'),channel=audio.getChannelData(0);ctx.clearRect(0,0,1000,120);ctx.strokeStyle='#29d7ce';ctx.beginPath();for(let x=0;x<1000;x++){let peak=0;const a=Math.floor(x*channel.length/1000),b=Math.max(a+1,Math.floor((x+1)*channel.length/1000));for(let n=a;n<b;n++)peak=Math.max(peak,Math.abs(channel[n]||0));ctx.moveTo(x,60-peak*55);ctx.lineTo(x,60+peak*55);}ctx.stroke();await $('zogg-audio').play();message('PREVIEW / '+Math.min(15,trim.duration).toFixed(2)+'s / audition only');}catch(e){if(version===revision&&id===requestId)message(e.message);}};
 async function importSound(kind){if(!selected||busy)return;const item={...selected},version=revision,track=+$('zogg-track').value;let trim;try{trim=trimSelection(item.duration_seconds,$('zogg-start').value,$('zogg-duration').value,kind);}catch(e){message(e.message);return;}busy=true;stop();controls();message('Preparing '+item.filename+'…');try{const r=await client.api('prepare',{asset_id:item.asset_id,...trim}),bytes=await client.audio(r.audio);if(version!==revision)throw Error('Selection changed; choose Load again');await load(new File([bytes],item.filename.replace(/\.[^.]+$/, '')+'.wav',{type:'audio/wav'}),kind,track);message(`LOADED / ${item.filename} / ${trim.start.toFixed(2)}s + ${r.duration.toFixed(2)}s / ${kind==='sample'?'SAMPLER':'TRACK '+(track+1)}`);notice(`Zogg: ${item.filename} loaded into ${kind==='sample'?'sampler':'track '+(track+1)}.`);}catch(e){message(e.message);}finally{busy=false;controls();}}
 $('zogg-sampler').onclick=()=>importSound('sample');$('zogg-tape').onclick=()=>importSound('tape');
 controls();if(client)paired.then(()=>client.api('status')).then(r=>{for(const library of r.libraries){const option=document.createElement('option');option.value=library.id;option.textContent=library.display_name+(library.volume_present?'':' / OFFLINE');$('zogg-library').append(option);}search();}).catch(e=>message(e.message));
 return{stop,active:local,client,ready:paired};
}
